import java.util.*;
import java.io.*;

public class Main {
    static class FlowNetwork {
        int n;
        List<List<int[]>> adj;

        public FlowNetwork(int n) {
            this.n = n;
            adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
        }

        public void addEdge(int u, int v, int cap) {
            adj.get(u).add(new int[]{v, cap, adj.get(v).size()});
            adj.get(v).add(new int[]{u, 0, adj.get(u).size() - 1});
        }

        int[] levels;
        int[] it;

        public void buildLevels(int s) {
            levels = new int[n];
            Arrays.fill(levels, -1);
            levels[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int[] toRevCap : adj.get(v)) {
                    int to = toRevCap[0], cap = toRevCap[1];
                    if (cap > 0 && levels[to] < 0) {
                        levels[to] = levels[v] + 1;
                        q.offer(to);
                    }
                }
            }
        }

        public int sendFlow(int v, int t, int f) {
            if (v == t) return f;
            for (; it[v] < adj.get(v).size(); it[v]++) {
                int[] toRevCap = adj.get(v).get(it[v]);
                int to = toRevCap[0], cap = toRevCap[1], rev = toRevCap[2];
                if (cap > 0 && levels[v] < levels[to]) {
                    int pushed = sendFlow(to, t, Math.min(f, cap));
                    if (pushed > 0) {
                        adj.get(v).get(it[v])[1] -= pushed;
                        adj.get(to).get(rev)[1] += pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        public int maxFlow(int s, int t) {
            int flow = 0;
            while (true) {
                buildLevels(s);
                if (levels[t] < 0) break;
                it = new int[n];
                while (true) {
                    int pushed = sendFlow(s, t, Integer.MAX_VALUE);
                    if (pushed == 0) break;
                    flow += pushed;
                }
            }
            return flow;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int N = Integer.parseInt(br.readLine());
        int M = 3;

        int[] A = new int[M];
        int[] B = new int[M];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            B[i] = Integer.parseInt(st.nextToken());
        }

        int initial_total = 0;
        for (int i = 0; i < M; i++) {
            initial_total += Math.min(A[i], B[(i + 1) % M]);
        }

        FlowNetwork net = new FlowNetwork(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;

        for (int i = 0; i < M; i++) {
            net.addEdge(s, i, N);
            net.addEdge(M + i, t, B[i]);
            net.addEdge(i, M + i, A[i]);
            net.addEdge(i, M + ((i - 1 + M) % M), A[i]);
        }

        int max_flow_value = net.maxFlow(s, t);
        int answer = N - max_flow_value;

        System.out.println(answer + " " + initial_total);
    }
}
